-- ================================================================
-- CrimiReview -- rewritten wrong answer options (Easy, imported questions)
-- ================================================================
-- GENERATED by: dart run tools/rebalance_options.dart  (do not edit by hand)
-- Questions in this file: 202 (easy level only; each level has its own file)
--
-- Replaces ONLY the wrong options (text and reason). The question, the
-- correct option and the explanation stay as they are.
-- A question is changed only if its options are still exactly as they
-- were when the rewrite was made, so a Faculty edit is never overwritten.
-- Its version goes up by 1, so phones download the new options.
-- Safe to run more than once. To undo: supabase_rebalance_options_easy_rollback.sql
--
-- HOW TO RUN: Supabase Dashboard > SQL Editor > New query > paste > Run.
-- The result shows how many questions were changed and how many were skipped.
-- ================================================================

CREATE TEMP TABLE IF NOT EXISTS rebalance_input (
  id          TEXT PRIMARY KEY,
  old_options JSONB NOT NULL,
  new_options JSONB NOT NULL
);
TRUNCATE rebalance_input;


WITH changed AS (
  UPDATE public.questions q
  SET options = r.new_options,
      version = COALESCE(q.version, 1) + 1
  FROM rebalance_input r
  WHERE q.id = r.id
    AND q.options = r.old_options
  RETURNING q.id
)
SELECT
  (SELECT count(*) FROM changed) AS changed_now,
  (SELECT count(*) FROM rebalance_input r JOIN public.questions q ON q.id = r.id
     WHERE q.options = r.new_options) AS already_done_before,
  (SELECT count(*) FROM rebalance_input r LEFT JOIN public.questions q ON q.id = r.id
     WHERE q.id IS NULL OR (q.options <> r.new_options AND q.options <> r.old_options))
     AS skipped_edited_or_missing;
