  ('ca_005', $opt$[{"text":"For security and program placement","isCorrect":true,"rationale":"Inmates are classified based on security risk and needs for appropriate placement and programming.","is_correct":true},{"text":"For punishment levels","isCorrect":false,"rationale":"'For punishment levels' is incorrect. The correct answer is 'For security and program placement'. Inmates are classified based on security risk and needs for appropriate placement and programming. Review: Inmate Classification.","is_correct":false},{"text":"For food preferences","isCorrect":false,"rationale":"'For food preferences' is incorrect. The correct answer is 'For security and program placement'. Inmates are classified based on security risk and needs for appropriate placement and programming. Review: Inmate Classification.","is_correct":false},{"text":"For visiting schedules","isCorrect":false,"rationale":"'For visiting schedules' is incorrect. The correct answer is 'For security and program placement'. Inmates are classified based on security risk and needs for appropriate placement and programming. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"For security and program placement","isCorrect":true,"rationale":"Inmates are classified based on security risk and needs for appropriate placement and programming.","is_correct":true},{"text":"For assigning punishment levels","is_correct":false,"rationale":"Classification is not about extra punishment; it places inmates by security risk and needs."},{"text":"For grouping by home province","is_correct":false,"rationale":"Where an inmate comes from is not the basis of classification."},{"text":"For setting visiting schedules","is_correct":false,"rationale":"Visiting schedules are set by facility rules, not by classification."}]$opt$::jsonb),
