  ('ca_001', $opt$[{"text":"Punishment and rehabilitation","isCorrect":true,"rationale":"Imprisonment serves both as punishment for crimes and as an opportunity for rehabilitation.","is_correct":true},{"text":"Revenge only","isCorrect":false,"rationale":"'Revenge only' is incorrect. The correct answer is 'Punishment and rehabilitation'. Imprisonment serves both as punishment for crimes and as an opportunity for rehabilitation. Review: Institutional Corrections.","is_correct":false},{"text":"Entertainment","isCorrect":false,"rationale":"'Entertainment' is incorrect. The correct answer is 'Punishment and rehabilitation'. Imprisonment serves both as punishment for crimes and as an opportunity for rehabilitation. Review: Institutional Corrections.","is_correct":false},{"text":"Profit","isCorrect":false,"rationale":"'Profit' is incorrect. The correct answer is 'Punishment and rehabilitation'. Imprisonment serves both as punishment for crimes and as an opportunity for rehabilitation. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Punishment and rehabilitation","isCorrect":true,"rationale":"Imprisonment serves both as punishment for crimes and as an opportunity for rehabilitation.","is_correct":true},{"text":"Revenge for the victim's family","is_correct":false,"rationale":"Modern corrections rejects revenge as a purpose of imprisonment."},{"text":"Cheap labor for the state","is_correct":false,"rationale":"Inmate work is part of rehabilitation, not the purpose of imprisonment."},{"text":"Public shaming of offenders","is_correct":false,"rationale":"Shaming is not a purpose of imprisonment."}]$opt$::jsonb),
  ('ca_008', $opt$[{"text":"Bureau of Corrections (BUCOR)","isCorrect":true,"rationale":"The Bureau of Corrections (BUCOR) manages national penitentiaries for those sentenced to more than 3 years.","is_correct":true},{"text":"BJMP","isCorrect":false,"rationale":"'BJMP' is incorrect. The correct answer is 'Bureau of Corrections (BUCOR)'. The Bureau of Corrections (BUCOR) manages national penitentiaries for those sentenced to more than 3 years. Review: Institutional Corrections.","is_correct":false},{"text":"PNP","isCorrect":false,"rationale":"'PNP' is incorrect. The correct answer is 'Bureau of Corrections (BUCOR)'. The Bureau of Corrections (BUCOR) manages national penitentiaries for those sentenced to more than 3 years. Review: Institutional Corrections.","is_correct":false},{"text":"NBI","isCorrect":false,"rationale":"'NBI' is incorrect. The correct answer is 'Bureau of Corrections (BUCOR)'. The Bureau of Corrections (BUCOR) manages national penitentiaries for those sentenced to more than 3 years. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Bureau of Corrections (BUCOR)","isCorrect":true,"rationale":"The Bureau of Corrections (BUCOR) manages national penitentiaries for those sentenced to more than 3 years.","is_correct":true},{"text":"Bureau of Jail Management and Penology (BJMP)","is_correct":false,"rationale":"BJMP manages city, district and municipal jails, not national prisons."},{"text":"Parole and Probation Administration (PPA)","is_correct":false,"rationale":"The PPA supervises probationers and parolees in the community."},{"text":"Philippine National Police (PNP)","is_correct":false,"rationale":"The PNP holds arrested persons only briefly; it does not run national prisons."}]$opt$::jsonb),
  ('ca_011', $opt$[{"text":"Bureau of Jail Management and Penology","isCorrect":true,"rationale":"BJMP manages city, district, and municipal jails for those awaiting trial or serving sentences of 3 years or less.","is_correct":true},{"text":"Bureau of Justice Management","isCorrect":false,"rationale":"'Bureau of Justice Management' is incorrect. The correct answer is 'Bureau of Jail Management and Penology'. BJMP manages city, district, and municipal jails for those awaiting trial or serving sentences of 3 years or less. Review: Institutional Corrections.","is_correct":false},{"text":"Bureau of Juvenile Management","isCorrect":false,"rationale":"'Bureau of Juvenile Management' is incorrect. The correct answer is 'Bureau of Jail Management and Penology'. BJMP manages city, district, and municipal jails for those awaiting trial or serving sentences of 3 years or less. Review: Institutional Corrections.","is_correct":false},{"text":"Bureau of Judicial Process","isCorrect":false,"rationale":"'Bureau of Judicial Process' is incorrect. The correct answer is 'Bureau of Jail Management and Penology'. BJMP manages city, district, and municipal jails for those awaiting trial or serving sentences of 3 years or less. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Bureau of Jail Management and Penology","isCorrect":true,"rationale":"BJMP manages city, district, and municipal jails for those awaiting trial or serving sentences of 3 years or less.","is_correct":true},{"text":"Bureau of Jail Management and Parole","is_correct":false,"rationale":"The P stands for Penology; parole is handled by the Board of Pardons and Parole."},{"text":"Bureau of Justice Management and Penology","is_correct":false,"rationale":"The J stands for Jail, not Justice."},{"text":"Board of Jail Management and Protection","is_correct":false,"rationale":"It is a Bureau, not a Board, and the P stands for Penology."}]$opt$::jsonb),
  ('ca_012', $opt$[{"text":"Jail for short-term, prison for long-term","isCorrect":true,"rationale":"Jails hold those awaiting trial or short sentences; prisons hold those with longer sentences.","is_correct":true},{"text":"Same thing","isCorrect":false,"rationale":"'Same thing' is incorrect. The correct answer is 'Jail for short-term, prison for long-term'. Jails hold those awaiting trial or short sentences; prisons hold those with longer sentences. Review: Institutional Corrections.","is_correct":false},{"text":"Jail is larger","isCorrect":false,"rationale":"'Jail is larger' is incorrect. The correct answer is 'Jail for short-term, prison for long-term'. Jails hold those awaiting trial or short sentences; prisons hold those with longer sentences. Review: Institutional Corrections.","is_correct":false},{"text":"Prison is for women only","isCorrect":false,"rationale":"'Prison is for women only' is incorrect. The correct answer is 'Jail for short-term, prison for long-term'. Jails hold those awaiting trial or short sentences; prisons hold those with longer sentences. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Jail for short-term, prison for long-term","isCorrect":true,"rationale":"Jails hold those awaiting trial or short sentences; prisons hold those with longer sentences.","is_correct":true},{"text":"Jail for women, prison for men","is_correct":false,"rationale":"Both jails and prisons hold men and women; the difference is the length of the sentence."},{"text":"Jail is run by courts, prison by police","is_correct":false,"rationale":"Jails are run by BJMP and prisons by BuCor; neither is run by courts or police."},{"text":"They are the same facility","is_correct":false,"rationale":"Jails and prisons differ in who runs them and the length of sentences they hold."}]$opt$::jsonb),
